static volatile int g_boot_saw_low;

static void page_voice(void)
{
  char vb[40];
  const char *st = B->voice_msg[0] ? B->voice_msg : "READY";
  uint16_t col = C_CY;
  int lv0 = (int)((*(volatile uint32_t *)0x6000403cul) & 1);

  /* 通信状态用大字 + 颜色，隔一米也能看出现在在录音还是在收发。 */
  if (strncmp(st, "REC", 3) == 0)      { col = RGB(0xff, 0x50, 0x50); }
  else if (strncmp(st, "TX", 2) == 0)  { col = RGB(0xff, 0xc0, 0x40); }
  else if (strncmp(st, "RX", 2) == 0)  { col = RGB(0x50, 0xff, 0x90); }
  else                                  { col = C_CY; }

  text2(40, 30, "你好小黑", C_HI, C_BG);
  text2(12, 78, st, col, C_BG);

  /* 通信统计：这一句收/发了多少包、RSSI 多少，屏幕直接可读。 */
  if (B->rx_pkt > 0 || B->tx_pkt > 0)
    {
      if (B->rx_pkt > 0)
        {
          snprintf(vb, sizeof(vb), "PKT %d  RSSI %d", B->rx_pkt, B->rx_rssi);
        }
      else
        {
          snprintf(vb, sizeof(vb), "TX PKT %d", B->tx_pkt);
        }

      text_c(UI_W / 2, 110, vb, C_HI, C_BG);
    }

  snprintf(vb, sizeof(vb), "GPIO0=%d %s", lv0,
           g_boot_saw_low ? "SAW-LOW" : "NO-SIGNAL");
  text_c(UI_W / 2, 140, vb, g_boot_saw_low ? C_HI : C_DIM, C_BG);
  text_c(UI_W / 2, 168,
         B->touch_ok ? "点屏录音 3 秒" : "按 K1(BOOT) 录 3 秒",
         C_DIM2, C_BG);
}

