static void draw_page(int n)
{
  body_clear();

  switch (n)
    {
      case 0: page_voice(); break;
      case 1: page_reserved("IMAGE CODEC", "图像回传 · 生成式超压缩",
                            "图像语义编解码"); break;
      case 2: page_reserved("CHANNEL", "误码对抗 · 语义容错",
                            "信道误码仿真"); break;
      case 3: page_log(); break;
      default: page_rate(); break;
    }
}

