  B->rx_pkt  = pkt;
  B->rx_rssi = rssi;
  B->dirty   = 1;
}

void jx_ui_set_tx(int pkt)
{
  if (B == NULL) { return; }
  B->tx_pkt = pkt;
  B->dirty  = 1;
}

