from pathlib import Path
import argparse,hashlib,json,subprocess,sys
from serial.tools import list_ports

P=Path(__file__).resolve().parent.parent
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--role',required=True,choices=['COM12_TX','COM16_RX'])
parser.add_argument('--port')
args=parser.parse_args()
r=json.loads((P/'backup_manifest.json').read_text(encoding='utf8'))['roles'][args.role]
port=args.port or r['port']
image=P/r['firmware'];data=image.read_bytes()
assert len(data)==r['bytes'] and hashlib.sha256(data).hexdigest()==r['sha256'],'Firmware mismatch'
ports={p.device:p.hwid.lower() for p in list_ports.comports()}
