/* NSH launches foreground builtins while holding its local scheduler lock.
 * Keep the console and short control tasks on CPU0 so an inherited child
 * cannot run/exit on CPU1 before that launch/wait sequence is established.
 * The codec worker explicitly selects CPU1; radio I/O remains on CPU0. */
static void jx_find_console_pid(struct tcb_s *tcb, void *arg)
{
  if (strcmp(tcb->name, "nsh_main") == 0) { *(pid_t *)arg = tcb->pid; }
}

static void jx_pin_control_cpu(void)
{
  static int initialized;
  cpu_set_t cs;
  CPU_ZERO(&cs);
  CPU_SET(0, &cs);
  if (!initialized)
    {
      pid_t console = -1;
      nxsched_foreach(jx_find_console_pid, &console);
      if (console >= 0)
        {
          int rc = sched_setaffinity(console, sizeof(cs), &cs);
          printf("[control] console cpu=0 affinity_rc=%d\n", rc);
          if (rc == 0) { initialized = 1; }
        }
    }
  (void)sched_setaffinity(0, sizeof(cs), &cs);
}

