/* 开机自动接收：两块板上电就进入对讲待机；按 BOOT 时让出射频。 */
static int jx_radio_task(int argc, char *argv[])
  jx_ui_set_status("SENDING...");
  if (jx_ui_page_get() == 0) { jx_ui_page(0); }

  txargv[0] = "jixun";
  txargv[1] = "net";
  txargv[2] = "tx";
  txargv[3] = (char *)ip;
  txargv[4] = "2";
  txargv[5] = NULL;

  rc = jx_cmd_net_tx(5, txargv);
  jx_ui_set_status(rc == 0 ? "SENT" : "FAILED");
  if (jx_ui_page_get() == 0) { jx_ui_page(0); }
  return rc;
}

void jx_ui_send_action(void)
{
  jx_pin_control_cpu();
  const char *ip = jx_ui_peer_get();
  int pid;

  if (ip == NULL || ip[0] == '\0')
    {
      /* 没有对端 IP：走 LoRa 对讲。第一次按开始，第二次按结束。 */
      if (g_lora_tx_busy)
        {
          /* 录音循环每 40 ms 检查一次这个标志。编码/发送阶段收到也
           * 没有副作用；下一次录音开始时 ai_voice_stream_record()
           * 会把它清零。 */
          ai_voice_stream_finish();
          jx_ui_set_status("STOP REQ");
          jx_ui_log("BOOT stop request");
          return;
        }

      g_lora_tx_busy = 1;
      pid = task_create("lora-tx", 150, 65536, jx_ui_lora_send_task, NULL);
      if (pid < 0)
        {
          g_lora_tx_busy = 0;
          jx_ui_set_status("TASK FAIL");
          jx_ui_log("LoRa TX task fail");
          if (jx_ui_page_get() == 0) { jx_ui_page(0); }
          return;
        }

      /* The new TX task owns status and screen updates. It can preempt
       * this caller immediately, so redrawing here races its first page
       * update and can keep the foreground command waiting on the LCD. */
      return;
    }

  pid = task_create("jixun-send", 150, 32768, jx_ui_send_task, NULL);
  if (pid < 0)
    {
      jx_ui_set_status("TASK FAIL");
      if (jx_ui_page_get() == 0) { jx_ui_page(0); }
      return;
    }

  jx_ui_set_status("SENDING...");
  if (jx_ui_page_get() == 0) { jx_ui_page(0); }
}


static int jx_cmd_net_rx(int argc, char *argv[])
{
  int port = JX_NET_PORT_DEF;
  int timeout = 30;
  int rate_id = 0, bits = 0, ntok = 0, Tt = 0, orig_t = 0;
  uint32_t chunk = 0, last = 0;
  int64_t *idx = NULL;
  float *rec = NULL;
  int rc = 0;
  int nseg = 0;
  int voice_ready = 0;
  int buffered_play = jx_env_on("JX_BUFFER_PLAY", 0);
  int stream_play = jx_env_on("JX_STREAM_PLAY", 1) && !buffered_play;
  int play_muted = jx_env_on("JX_PLAY_MUTE", 0);
  int dual_half = jx_env_on("JX_DUAL_HALF", 0) && !play_muted;
  int dual_rx_first = jx_env_on("JX_DUAL_RX_FIRST", 0) && !play_muted;
  int stream_prebuffer_ms = jx_env_int("JX_STREAM_PREBUFFER", 100);
  struct jx_playbuf_s playbuf;
  struct jx_playbuf_s *playbuf_p = NULL;
  pthread_t play_thread;
  int play_thread_on = 0;
  int16_t *buffered_out = NULL;
  int buffered_n = 0;
  uint32_t next_chunk = 0;
  int total_chunks = jx_env_int("JX_RX_CHUNKS", 4);
  int use_inc_dec = jx_env_on("JX_DEC_INCREMENTAL", 1);
  SDecState *sdec_state = NULL;
  double t_start;
  double t_audio = 0;

  if (total_chunks < 1) { total_chunks = 1; }

  if (argc >= 4) { port = atoi(argv[3]); }
  if (argc >= 5) { timeout = atoi(argv[4]); }
  if (timeout < 3) { timeout = 3; }

  if (jx_env_on("JX_DHCPD", 0))
    {
#ifdef CONFIG_NETUTILS_DHCPD
      int dhcprc = dhcpd_start("wlan0");
      printf("[net] DHCPD rc=%d\n", dhcprc);
      usleep(500 * 1000);
#else
      printf("[net] DHCPD 未编入本固件（CONFIG_NETUTILS_DHCPD=n）\n");
#endif
    }

  printf("=== 极讯 Codec 接收端 (码率 %s) 端口 %d ===\n", jx_rate_name(), port);
  t_start = jx_now_ms();

  if (use_inc_dec)
    {
      sdec_state = sdec_new();
      printf("[dec] 增量解码器就绪，arena 峰值 %u floats (%.1f MB)\n",
             (unsigned)sdec_peak(sdec_state),
             (double)sdec_peak(sdec_state) * 4.0 / 1048576.0);
    }

  if (jx_ui_ready())
"}

