static int jx_ui_lora_send_task(int argc, char *argv[])
{
  int rc;
  int secs = 3;
  const char *e = getenv("JX_UI_TAKE_SEC");

  (void)argc;
  (void)argv;

  if (e != NULL)
    {
      int v = atoi(e);
      if (v >= 1 && v <= 8) { secs = v; }
    }

  /* 开机自启的 UI 任务看不到 NSH 里 set 的环境变量，这里补上对讲机
   * 默认参数；不补的话 BOOT 触发会退回 SF=7，而接收端是 SF=8，
   * 扩频因子对不上，包根本收不到。 */
  if (getenv("JX_LORA_SF") == NULL)  { setenv("JX_LORA_SF", "8", 1); }
  if (getenv("JX_LORA_BW") == NULL)  { setenv("JX_LORA_BW", "0x06", 1); }
  setenv("JX_LORA_DBM", "22", 1);
  if (getenv("JX_PAD_MS") == NULL)   { setenv("JX_PAD_MS", "257", 1); }
  if (getenv("JX_PF") == NULL)       { setenv("JX_PF", "0", 1); }
  /* 每包只发一次。2 秒语音约 26 个唯一包，重复两次会让空口多等 2 秒；
   * 现场 RSSI 约 -22 dBm，单发足够，K7 仍按序号补丢包。 */
  if (getenv("JX_LORA_TX_REPEAT") == NULL) { setenv("JX_LORA_TX_REPEAT", "1", 1); }

  /* 关键：UI 触发是"按一次录满 3 秒"，不是按住说话。
   * JX_PTT 残留会让录音线程一看到松手就结束，实测只剩 -5 ms。 */
  setenv("JX_PTT", "0", 1);
  /* 两声短音结束后才开始录音，避免用户还在等提示音时先丢字。 */
  if (getenv("JX_BEEP") == NULL) { setenv("JX_BEEP", "1", 1); }
  /* UI 侧 dump 开关；本函数运行在按键任务里，必须在这里 setenv 才生效。 */
  setenv("JX_PCM_DUMP", g_ui_pcm_dump ? "1" : "0", 1);
  /* 2026-10-30: 固定输入测试，用内嵌 3 秒 PCM 走完整发送链路。 */
  setenv("JX_TX_PCM_BLOB", g_ui_tx_blob ? "1" : "0", 1);
  /* 2026-10-29: 第二次录音实测 recording done: -5 ms / queued=0，
   * ADC 完全没采到数据。每次按键都强制把 I2S/码片整条重新初始化。 */
  setenv("JX_AI_REINIT", "0", 1);
  if (getenv("JX_TX_AFTER_REC") == NULL) { setenv("JX_TX_AFTER_REC", "0", 1); }
  /* 2026-10-29: 保持上电累积到第 3 次 ADC 就全 0（probe nz=0 acrms=0）。
   * 改成每次冷启动 + 1.5 s 预挂，让 PGA 重新起振。 */
  /* 每次发送后不能断 ES8311 模拟电源。冷启动后 PGA 要重新建立，
   * 现场表现为第一次有声音、后几次只剩开头一小段。 */
  setenv("JX_ADC_POWEROFF", "0", 1);
  setenv("JX_PREARM_MS", "0", 1); /* settle after the cue, before capture */
  /* 2026-10-29: UI 路径原来没设 PREARM，退回了默认 2000 ms。
   * 加上提示音 2.7 s，用户按下 BOOT 后要等 5 秒才真正开始采集，
   * 说完话程序才开始录，录到的基本是静音。降到 300 ms 硬下限，
   * 使「第三声长音结束」到「开始录音」只差 0.3 秒。 */
  setenv("JX_PREARM_MS", "0", 1); /* settle after the cue, before capture */

  /* 录音期间保持 BOOT 可用：第二次按键 = 说完，立即结束录音。
   * g_lora_tx_busy 会挡住重复创建发送任务。 */
  jx_ui_set_boot_enable(1);

  /* 2026-10-29: 接收任务退出不是瞬间完成：它还要解完最后一段、把播放
   * 缓冲放完、再 jx_lora_release()。原来这里盲等 1.5 s，连按第三次时
   * 经常正好撞进这段收尾：发送端刚 lora_open，接收端后脚 release 把
   * 芯片关掉，日志就是 TX rc=0 但对端 0 包。改成等接收任务真正退出。 */
  {
    int waited = 0;
    char st[32];

    if (g_lora_rx_active)
      {
        snprintf(st, sizeof(st), "WAIT RADIO %d", secs);
        jx_ui_set_status(st);
      }

    while (g_lora_rx_active && waited < 12000)
      {
        usleep(20 * 1000);
        waited += 20;
      }

    printf("[ui] radio handover wait %d ms (rx_active=%d)\n",
           waited, g_lora_rx_active);
    printf("[txstep] A1 before ui_log\n");
    jx_ui_log("LoRa handover ok");
    printf("[txstep] A2 after ui_log\n");
    usleep(10 * 1000); /* handover completion is checked above; audio setup follows */
    printf("[txstep] A3 after sleep\n");                /* 芯片彻底落定再重配 */
  }

  {
    char st[32];
    snprintf(st, sizeof(st), "REC PREP %ds", secs);
    jx_ui_set_status(st);
  }
  printf("[txstep] A4 before TX start\n");
